Rules.InvariantScript:
Set(gblHsSlip, Trim(txtHsSlip.Text));Set(gblHsRecipient, Trim(txtHsRecipient.Text));Set(gblHsDept, Trim(txtHsDept.Text));Set(gblHsDd, "");
If(
    !IsBlank(gblHsFrom) && !IsBlank(gblHsTo) && gblHsFrom > gblHsTo,
    Notify("通知日時の開始が終了より後になっています", NotificationType.Warning),
    // TODO: 受取人・受取部署・処理状態・データ区分・通知日時の API 連携は未対応 (現状は伝票番号のみ search_keyword で送信)
    Set(varHistSearch, gblHsSlip);Set(gblPage, 1);Set(gblHsRun, true)
)

With(
    {raw: IfError(With({apiResult: 'EDS-APIManagement1'.Run("history", JSON({search_keyword: Coalesce(varHistSearch, ""), tz_offset: TimeZoneOffset()}), "historyExport")}, If(!IsBlank(Trim(Coalesce(Text(apiResult.error), ""))), Set(varNotifyErrorMessage, Text(apiResult.error)); Set(varShowNotifyFailed, true); "", Set(varShowNotifyFailed, false); apiResult.response)), Set(varNotifyErrorMessage, "Power Automate のフローに接続できません"); Set(varShowNotifyFailed, true); "")},
    If(
        IsBlank(raw) || Left(raw, 8) = "{""error""",
        If(varShowNotifyFailed, false, Notify("ダウンロードに失敗しました", NotificationType.Error)),
        Notify(Text(ParseJSON(raw).rowCount) & " 件をダウンロードします", NotificationType.Success);
        Download(Text(ParseJSON(raw).file.url))
    )
)
